code:
  language: csharp
  harness: statements
  source: |
    int stock = 10;
    int balance = 500;
    int shipments = 0;

    var steps = new List<Step>
    {
        new Step("ReserveStock", () => stock -= 1, () => stock += 1),
        new Step("ChargePayment", () => Charge(600), () => balance += 600),
        new Step("CreateShipment", () => shipments += 1, () => shipments -= 1),
    };
    var completed = new List<Step>();

    try
    {
        foreach (var step in steps)
        {
            step.Execute();
            completed.Add(step);
        }
    }
    catch (InvalidOperationException)
    {
        // Compensate in reverse order.
        foreach (var step in Enumerable.Reverse(steps))
        {
            step.Compensate();
        }
    }

    Console.WriteLine($"Stock: {stock}, Balance: {balance}, Shipments: {shipments}");

    void Charge(int amount)
    {
        if (balance < amount)
            throw new InvalidOperationException("Insufficient funds");
        balance -= amount;
    }

    record Step(string Name, Action Execute, Action Compensate);
bugLineSets: [[24]]
fixedSource: |
  int stock = 10;
  int balance = 500;
  int shipments = 0;

  var steps = new List<Step>
  {
      new Step("ReserveStock", () => stock -= 1, () => stock += 1),
      new Step("ChargePayment", () => Charge(600), () => balance += 600),
      new Step("CreateShipment", () => shipments += 1, () => shipments -= 1),
  };
  var completed = new List<Step>();

  try
  {
      foreach (var step in steps)
      {
          step.Execute();
          completed.Add(step);
      }
  }
  catch (InvalidOperationException)
  {
      // Compensate only the steps that committed, in reverse order.
      foreach (var step in Enumerable.Reverse(completed))
      {
          step.Compensate();
      }
  }

  Console.WriteLine($"Stock: {stock}, Balance: {balance}, Shipments: {shipments}");

  void Charge(int amount)
  {
      if (balance < amount)
          throw new InvalidOperationException("Insufficient funds");
      balance -= amount;
  }

  record Step(string Name, Action Execute, Action Compensate);
fixedExpect: { kind: output, value: "Stock: 10, Balance: 500, Shipments: 0" }
